// @ts-check
import starlight from '@astrojs/starlight';
import { defineConfig } from 'astro/config';
import starlightLlmsTxt from 'starlight-llms-txt';
import { createStarlightTypeDocPlugin } from 'starlight-typedoc';

// One API reference per package, each generated by TypeDoc from the TSDoc in its source.
const packages = [
  { name: 'acp', label: '@deft-subspace/acp', entryPoints: ['../packages/acp/src/index.ts', '../packages/acp/src/node.ts'] },
  { name: 'kernel', label: '@deft-subspace/kernel', entryPoints: ['../packages/kernel/src/index.ts', '../packages/kernel/src/node.ts'] },
  { name: 'testkit', label: '@deft-subspace/acp-testkit', entryPoints: ['../packages/testkit/src/index.ts', '../packages/testkit/src/node.ts'] },
  { name: 'devtools', label: '@deft-subspace/devtools', entryPoints: ['../packages/devtools/src/index.ts'] },
];
const reference = packages.map((pkg) => {
  const [plugin, sidebarGroup] = createStarlightTypeDocPlugin();
  return {
    sidebarGroup,
    plugin: plugin({
      entryPoints: pkg.entryPoints,
      tsconfig: `../packages/${pkg.name}/tsconfig.json`,
      output: `reference/typescript/${pkg.name}`,
      sidebar: { label: pkg.label, collapsed: true },
      typeDoc: { excludeInternal: true, excludePrivate: true, excludeExternals: true, readme: 'none', gitRevision: 'experiment/deft-subspace-prototype' },
    }),
  };
});

export default defineConfig({
  // Where the site would be published (GitHub Pages for deftai/subspace). Not published yet.
  site: 'https://deftai.github.io',
  base: '/subspace',
  integrations: [
    starlight({
      title: 'Subspace',
      description: 'ACP for apps and agents: one model over protocol v1 and v2, turns you can await, cancellation that works.',
      social: [{ icon: 'github', label: 'GitHub', href: 'https://github.com/deftai/subspace' }],
      editLink: { baseUrl: 'https://github.com/deftai/subspace/edit/experiment/deft-subspace-prototype/site/' },
      lastUpdated: true,
      plugins: [...reference.map((r) => r.plugin), starlightLlmsTxt({ projectName: 'Subspace' })],
      sidebar: [
        { label: 'Start', items: ['getting-started', 'concepts'] },
        {
          label: 'Clients',
          items: ['client/starting-agents', 'client/handlers', 'client/turns', 'client/permissions', 'client/cancelling', 'client/sessions', 'client/questions'],
        },
        { label: 'Agents', items: ['agents/writing-an-agent', 'agents/extensions'] },
        { label: 'MCP', items: ['mcp/servers', 'mcp/over-acp'] },
        { label: 'Terminals and background work', items: ['background/terminals', 'background/background-work'] },
        { label: 'Testing', items: ['testing/testkit', 'testing/devtools'] },
        { label: 'Behaviour', items: ['behaviour/conformance', 'behaviour/quirks', 'behaviour/protocol-versions'] },
        { label: 'Kernel', items: ['kernel'] },
        { label: 'Reference: TypeScript', items: reference.map((r) => r.sidebarGroup) },
        { label: 'Project', items: ['status'] },
      ],
    }),
  ],
});
